"""Resume upload, storage and analysis.

Security rules enforced here:
  * only PDFs: file extension, declared content type AND the %PDF- signature must agree
  * size limit (RESUME_MAX_MB) and page limit (RESUME_MAX_PAGES)
  * the stored file name is generated by the server (uuid), never taken from the client
  * every lookup is scoped to the logged-in student; another student's resume is "not found"
"""
import os
import re
import uuid
from pathlib import Path

from fastapi import HTTPException, status
from sqlalchemy.orm import Session

from app.ai.resume.analyze import (
    JobDoc,
    analyze_text,
    compare_with_profile,
    completeness,
    job_relevance,
    potentially_missing_skills,
    profile_suggestions,
)
from app.ai.resume.extract import ResumeExtractionError, extract_pdf_text
from app.ai.resume.parse import find_resume_cgpa
from app.ai.resume.sections import SECTION_LABELS
from app.ai.resume.skills import DetectedSkill, SkillMatcher
from app.core.config import get_settings
from app.models import (
    Job,
    JobStatus,
    Resume,
    ResumeAnalysis,
    ResumeDetectedSkill,
    SkillImportance,
    SkillSource,
    Student,
    StudentSkill,
    User,
)
from app.repositories import job_repository, resume_repository
from app.schemas.resume import (
    ContactOut,
    DetectedSkillOut,
    EducationEntry,
    EntryOut,
    JobRelevanceOut,
    MissingSkillOut,
    ProfileComparisonOut,
    ProfileSkillRef,
    ResumeAnalysisOut,
    ResumeOut,
    ScorePartOut,
    SectionOut,
    SuggestionOut,
)
from app.services import profile_service, recommendation_service

ALLOWED_CONTENT_TYPES = {"application/pdf", "application/x-pdf", "application/octet-stream"}
CORE_SECTIONS = {"education", "skills", "projects"}
SEVERITY_ORDER = {"high": 0, "medium": 1, "low": 2}
DISCLAIMER = (
    "This is an automated, keyword-based analysis. It can miss or misread content, especially with unusual "
    "layouts, and it is not a judgement of your ability. Use it as a checklist, not a verdict."
)


def _error(code: int, detail: str) -> HTTPException:
    return HTTPException(code, detail)


# ---------- file handling ----------
def safe_display_name(filename: str | None) -> str:
    name = os.path.basename((filename or "resume.pdf").replace("\\", "/"))
    name = re.sub(r"[\x00-\x1f\x7f]", "", name).strip()
    return (name or "resume.pdf")[:255]


def validate_upload_meta(filename: str | None, content_type: str | None) -> None:
    """Checks that need no file content (run before reading the body)."""
    if not filename or not filename.lower().endswith(".pdf"):
        raise _error(status.HTTP_415_UNSUPPORTED_MEDIA_TYPE, "Only PDF files (.pdf) are supported.")
    if (content_type or "").split(";")[0].strip().lower() not in ALLOWED_CONTENT_TYPES:
        raise _error(status.HTTP_415_UNSUPPORTED_MEDIA_TYPE, "Only PDF files are supported.")


def validate_upload_bytes(data: bytes) -> None:
    max_bytes = get_settings().resume_max_bytes
    if len(data) == 0:
        raise _error(422, "The uploaded file is empty.")
    if len(data) > max_bytes:
        raise _error(413, f"The file is too large. The maximum size is {get_settings().resume_max_mb} MB.")
    if not data.startswith(b"%PDF-"):
        raise _error(status.HTTP_415_UNSUPPORTED_MEDIA_TYPE, "This file is not a valid PDF.")


def _resolve(relative: str) -> Path:
    root = get_settings().upload_path.resolve()
    path = (root / relative).resolve()
    if root not in path.parents:  # defence in depth against path tricks
        raise _error(status.HTTP_404_NOT_FOUND, "File not found.")
    return path


def _remove_file(relative: str) -> None:
    try:
        _resolve(relative).unlink(missing_ok=True)
    except (OSError, HTTPException):
        pass  # a leftover file is harmless; never fail the request over it


# ---------- loading the data analysis needs ----------
def _open_jobs(db: Session) -> list[Job]:
    filters = job_repository.JobFilters(status=JobStatus.OPEN, hide_expired=True)
    return job_repository.search_jobs(db, filters, recommendation_service.CANDIDATE_LIMIT, 0)[0]


def _job_docs(jobs: list[Job]) -> list[JobDoc]:
    docs = []
    for job in jobs:
        profile = recommendation_service.build_job_profile(job)
        skills = [(js.skill_id, js.skill.name, js.importance == SkillImportance.REQUIRED, js.weight) for js in job.skills]
        docs.append(JobDoc(job.id, job.title, job.company.name, profile.text, skills))
    return docs


def _run_analysis(db: Session, extracted_text: str, page_count: int):
    matcher = SkillMatcher(resume_repository.skill_catalog(db))
    jobs = _open_jobs(db)
    corpus = [d.text for d in _job_docs(jobs)]
    return analyze_text(extracted_text, page_count, matcher, corpus)


def _new_analysis_row(result) -> ResumeAnalysis:
    return ResumeAnalysis(
        completeness_score=result.completeness_score,
        detected_name=result.detected_name,
        word_count=result.word_count,
        page_count=result.page_count,
        sections=result.sections,
        contact=result.contact,
        keywords=result.keywords,
        education=result.education,
        projects=result.projects,
        experience=result.experience,
        certifications=result.certifications,
        suggestions=[s.as_dict() for s in result.suggestions],
        detected_skills=[
            ResumeDetectedSkill(skill_id=d.skill_id, evidence=",".join(d.evidence)) for d in result.skills
        ],
    )


# ---------- use cases ----------
def upload_resume(db: Session, user: User, filename: str | None, content_type: str | None, data: bytes) -> ResumeAnalysisOut:
    student = profile_service.get_student(db, user)
    validate_upload_bytes(data)
    try:
        extracted = extract_pdf_text(data, get_settings().resume_max_pages)
    except ResumeExtractionError as exc:
        raise _error(exc.status_code, exc.message) from exc
    result = _run_analysis(db, extracted.text, extracted.page_count)

    relative = f"resumes/{uuid.uuid4().hex}.pdf"
    path = _resolve(relative)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(data)

    previous = resume_repository.list_all(db, student.id)
    old_files = [r.file_path for r in previous]
    try:
        resume = Resume(
            student_id=student.id, file_path=relative, original_name=safe_display_name(filename),
            mime_type="application/pdf", size_bytes=len(data), extracted_text=result.cleaned_text, is_active=True,
        )
        resume.analysis = _new_analysis_row(result)
        db.add(resume)
        for old in previous:  # one resume per student: the new upload replaces the old one
            db.delete(old)
        db.commit()
    except Exception:
        db.rollback()
        _remove_file(relative)
        raise
    for name in old_files:
        _remove_file(name)
    return analysis_out(db, student, resume_repository.get_owned(db, resume.id, student.id))


def current_resume(db: Session, user: User) -> ResumeOut | None:
    student = profile_service.get_student(db, user)
    resume = resume_repository.get_current(db, student.id)
    return _resume_out(resume) if resume else None


def get_owned_or_404(db: Session, user: User, resume_id: int) -> tuple[Student, Resume]:
    student = profile_service.get_student(db, user)
    resume = resume_repository.get_owned(db, resume_id, student.id)
    if resume is None:
        raise _error(status.HTTP_404_NOT_FOUND, "Resume not found.")
    return student, resume


def get_analysis(db: Session, user: User, resume_id: int) -> ResumeAnalysisOut:
    student, resume = get_owned_or_404(db, user, resume_id)
    return analysis_out(db, student, resume)


def reanalyze(db: Session, user: User, resume_id: int) -> ResumeAnalysisOut:
    """Run the analysis again on the stored text (e.g. after the skills list or jobs changed)."""
    student, resume = get_owned_or_404(db, user, resume_id)
    if not resume.extracted_text:
        raise _error(422, "There is no stored text to analyse. Upload the resume again.")
    result = _run_analysis(db, resume.extracted_text, resume.analysis.page_count if resume.analysis else 1)
    # Remove the old analysis first and flush: inserting the new row before the old one is deleted
    # would break the "one analysis per resume" unique constraint.
    resume.analysis = None
    db.flush()
    resume.analysis = _new_analysis_row(result)
    db.commit()
    return analysis_out(db, student, resume_repository.get_owned(db, resume.id, student.id))


def delete_resume(db: Session, user: User, resume_id: int) -> None:
    _, resume = get_owned_or_404(db, user, resume_id)
    relative = resume.file_path
    db.delete(resume)
    db.commit()
    _remove_file(relative)


def file_for_download(db: Session, user: User, resume_id: int) -> tuple[Path, str]:
    _, resume = get_owned_or_404(db, user, resume_id)
    path = _resolve(resume.file_path)
    if not path.is_file():
        raise _error(status.HTTP_404_NOT_FOUND, "The resume file is no longer available.")
    return path, resume.original_name


def sync_skills(db: Session, user: User, resume_id: int) -> ResumeAnalysisOut:
    """Add the skills detected in the resume to the student's profile (marked as coming from the resume)."""
    student, resume = get_owned_or_404(db, user, resume_id)
    have = {s.skill_id for s in student.skills}
    for ds in resume.analysis.detected_skills:
        if ds.skill_id not in have:
            student.skills.append(StudentSkill(skill_id=ds.skill_id, source=SkillSource.RESUME))
    db.commit()
    db.expire_all()
    student, resume = get_owned_or_404(db, user, resume_id)
    return analysis_out(db, student, resume)


# ---------- building the response ----------
def _resume_out(resume: Resume) -> ResumeOut:
    return ResumeOut(
        id=resume.id, original_name=resume.original_name, size_bytes=resume.size_bytes,
        page_count=resume.analysis.page_count if resume.analysis else None, uploaded_at=resume.uploaded_at,
    )


def analysis_out(db: Session, student: Student, resume: Resume) -> ResumeAnalysisOut:
    a = resume.analysis
    if a is None:
        raise _error(status.HTTP_404_NOT_FOUND, "This resume has not been analysed yet.")

    profile_skill_ids = {s.skill_id for s in student.skills}
    profile_skill_names = {s.skill_id: s.skill.name for s in student.skills}
    detected = [
        DetectedSkill(ds.skill_id, ds.skill.name, ds.skill.category, [e for e in (ds.evidence or "").split(",") if e])
        for ds in a.detected_skills
    ]
    detected.sort(key=lambda d: d.name.lower())
    resume_skill_ids = {d.skill_id for d in detected}

    # --- live comparisons (profile + current open jobs) ---
    docs = _job_docs(_open_jobs(db))
    relevance = job_relevance(resume.extracted_text or "", resume_skill_ids, docs, limit=5)
    have_names = {d.name.lower() for d in detected} | {n.lower() for n in profile_skill_names.values()}
    potential = potentially_missing_skills(relevance, have_names)
    education = a.education or []
    comparison = compare_with_profile(
        detected, profile_skill_ids, profile_skill_names,
        find_resume_cgpa(education), float(student.cgpa) if student.cgpa is not None else None,
    )
    profile_missing = profile_service.compute_completeness(student).missing
    live = profile_suggestions(comparison, potential, profile_missing)
    suggestions = sorted(
        [*(a.suggestions or []), *(s.as_dict() for s in live)], key=lambda s: SEVERITY_ORDER[s["severity"]]
    )

    found_keys = list(a.sections or [])
    all_keys = ["summary", "education", "skills", "projects", "experience", "certifications"]
    section = lambda k: SectionOut(key=k, label=SECTION_LABELS[k], required=k in CORE_SECTIONS)
    _, breakdown = completeness(
        a.contact or {}, a.detected_name, found_keys, education, a.projects or [], a.experience or [],
        a.certifications or [], len(detected), a.word_count or 0,
    )

    return ResumeAnalysisOut(
        resume=_resume_out(resume),
        detected_name=a.detected_name,
        word_count=a.word_count or 0,
        page_count=a.page_count or 0,
        completeness_score=a.completeness_score or 0,
        score_breakdown=[ScorePartOut(**p) for p in breakdown],
        sections_found=[section(k) for k in all_keys if k in found_keys],
        sections_missing=[section(k) for k in all_keys if k not in found_keys],
        contact=ContactOut(**{k: bool((a.contact or {}).get(k)) for k in ("email", "phone", "linkedin", "github")}),
        education=[EducationEntry(**e) for e in education],
        projects=[EntryOut(**p) for p in (a.projects or [])],
        experience=[EntryOut(**e) for e in (a.experience or [])],
        certifications=a.certifications or [],
        skills=[
            DetectedSkillOut(skill_id=d.skill_id, name=d.name, category=d.category, evidence=d.evidence,
                             in_profile=d.skill_id in profile_skill_ids)
            for d in detected
        ],
        keywords=a.keywords or [],
        potentially_missing_skills=[MissingSkillOut(**p) for p in potential],
        job_relevance=[JobRelevanceOut(**vars(r)) for r in relevance],
        profile_comparison=ProfileComparisonOut(
            skills_not_in_profile=[ProfileSkillRef(**s) for s in comparison["skills_not_in_profile"]],
            skills_not_on_resume=comparison["skills_not_on_resume"],
            resume_cgpa=comparison["resume_cgpa"],
            profile_cgpa=comparison["profile_cgpa"],
            cgpa_mismatch=comparison["cgpa_mismatch"],
            missing_profile_information=profile_missing,
        ),
        suggestions=[SuggestionOut(**s) for s in suggestions],
        disclaimer=DISCLAIMER,
    )
